package com.quicknotes.app;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import org.json.*;import java.util.*;
/** Foreground alarm audio survives the app going into the background. */
public class AlarmService extends Service {
 static final int NOTIFICATION=7001;static final String CHANNEL="ringing-alarms-v2";
 static volatile AlarmService current;final LinkedHashMap<String,Long> ringing=new LinkedHashMap<>();MediaPlayer player;Vibrator vibrator;PowerManager.WakeLock wake;AudioManager audio;AudioFocusRequest focus;Handler timer=new Handler(Looper.getMainLooper());
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();current=this;}
 static void reconcile(Context c,JSONObject data){AlarmService service=current;if(service==null)return;service.timer.post(()->{try{for(String id:new ArrayList<>(service.ringing.keySet())){JSONObject i=Reminders.find(data,id);if(i==null||i.optBoolean("done")||i.optBoolean("deleted")||!i.optBoolean("urgent")||i.optLong("due")!=service.ringing.get(id)||!Reminders.activeList(data,i.optString("list")))service.ringing.remove(id);}if(service.ringing.isEmpty())service.stopSelf();else service.startForeground(NOTIFICATION,service.notification());}catch(Exception e){service.stopSelf();}});}
 static Intent command(Context c,String action,String id){return new Intent(c,AlarmService.class).setAction(action).putExtra("id",id);}
 public int onStartCommand(Intent intent,int flags,int startId){if(intent==null){stopSelf();return START_NOT_STICKY;}String id=intent.getStringExtra("id"),action=intent.getAction();try{
  if("STOP".equals(action)||"SNOOZE".equals(action)||"COMPLETE".equals(action)){if("COMPLETE".equals(action)){synchronized(MainActivity.STORE_LOCK){JSONObject d=Reminders.read(this);JSONObject completeItem=Reminders.find(d,id);if(completeItem!=null&&!completeItem.optBoolean("done")&&!completeItem.optBoolean("deleted"))Repeats.complete(d,id,System.currentTimeMillis());Reminders.write(this,d);Reminders.schedule(this,d);}sendBroadcast(new Intent(getPackageName()+".DATA_CHANGED").setPackage(getPackageName()));}if("SNOOZE".equals(action)){synchronized(MainActivity.STORE_LOCK){JSONObject data=Reminders.read(this),item=Reminders.find(data,id);if(item!=null&&!item.optBoolean("done")&&!item.optBoolean("deleted")){getSharedPreferences(Reminders.PREFS,0).edit().putLong("snooze:"+id,System.currentTimeMillis()+5*60*1000).putLong("snooze-due:"+id,item.optLong("due")).apply();Reminders.schedule(this,data);}}}ringing.remove(id);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(id,id.hashCode());if(ringing.isEmpty())stopSelf();else startForeground(NOTIFICATION,notification());sendBroadcast(new Intent(getPackageName()+".ALARM_CHANGED").setPackage(getPackageName()));return START_NOT_STICKY;}
  synchronized(MainActivity.STORE_LOCK){JSONObject item=Reminders.find(Reminders.read(this),id);if(item==null||item.optBoolean("done")||item.optBoolean("deleted")||!item.optBoolean("urgent")||item.optLong("due")!=intent.getLongExtra("expectedDue",-1)){if(ringing.isEmpty())stopSelf();return START_NOT_STICKY;}ringing.put(id,item.optLong("due"));}
  startForeground(NOTIFICATION,notification());if(player==null)startSound();MainActivity.showRingingAlarm();timer.removeCallbacks(timeout);timer.postDelayed(timeout,5*60*1000);sendBroadcast(new Intent(getPackageName()+".ALARM_CHANGED").setPackage(getPackageName()));
 }catch(Exception e){android.util.Log.e("QuickNotes","Alarm start failed",e);stopSelf();}return START_NOT_STICKY;}
 JSONObject itemFor(String id)throws Exception{synchronized(MainActivity.STORE_LOCK){return Reminders.find(Reminders.read(this),id);}}
 final Runnable timeout=()->stopSelf();
 Notification notification()throws Exception{String id=ringing.keySet().iterator().next();JSONObject item; synchronized(MainActivity.STORE_LOCK){item=Reminders.find(Reminders.read(this),id);}NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel(CHANNEL,"Urgent reminder alarms",NotificationManager.IMPORTANCE_HIGH);channel.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());channel.enableVibration(true);channel.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);nm.createNotificationChannel(channel);
  Intent screen=AlarmActivity.intent(this,id);ActivityOptions options=ActivityOptions.makeBasic();if(Build.VERSION.SDK_INT>=35)options.setPendingIntentCreatorBackgroundActivityStartMode(ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOWED);PendingIntent open=PendingIntent.getActivity(this,id.hashCode(),screen,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE,options.toBundle());
  PendingIntent stop=PendingIntent.getService(this,0,command(this,"STOP",id).setData(Uri.parse("quicknotes://stop/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  PendingIntent complete=PendingIntent.getService(this,0,command(this,"COMPLETE",id).setData(Uri.parse("quicknotes://complete/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  PendingIntent snooze=PendingIntent.getService(this,0,command(this,"SNOOZE",id).setData(Uri.parse("quicknotes://snooze/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Notification.Builder b=new Notification.Builder(this,CHANNEL).addExtras(item==null?new Bundle():PhotoMetadata.extras(this,item)).setSmallIcon(R.drawable.ic_notification).setContentTitle(item==null?"Urgent Reminder":item.optString("title")).setContentText(item==null?"":item.optString("notes")).setStyle(new Notification.BigTextStyle().bigText(item==null?"":item.optString("notes"))).setOnlyAlertOnce(true).setCategory(Notification.CATEGORY_ALARM).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(true).setContentIntent(open).addAction(new Notification.Action.Builder(null,"Dismiss",stop).build()).addAction(new Notification.Action.Builder(null,"Mark As Completed",complete).build());
  b.addAction(new Notification.Action.Builder(null,"Snooze 5 min",snooze).build());if(item!=null&&item.optBoolean("flag")&&(Build.VERSION.SDK_INT<34||nm.canUseFullScreenIntent()))b.setFullScreenIntent(open,true);return b.build();
 }
 void startSound()throws Exception{wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"QuickNotes:urgent-alarm");wake.acquire(6*60*1000L);AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build();audio=(AudioManager)getSystemService(AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(attrs).setOnAudioFocusChangeListener(change->{}).build();audio.requestAudioFocus(focus);Uri sound=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);try{player=preparePlayer(attrs,sound,false);}catch(Exception unavailable){android.util.Log.i("QuickNotes","System alarm sound unavailable; using bundled tone");player=preparePlayer(attrs,null,true);}vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator!=null)vibrator.vibrate(VibrationEffect.createWaveform(new long[]{0,600,400,600,1000},0),attrs);}
 MediaPlayer preparePlayer(AudioAttributes attrs,Uri sound,boolean fallback)throws Exception{MediaPlayer candidate=new MediaPlayer();try{candidate.setAudioAttributes(attrs);if(fallback){try(android.content.res.AssetFileDescriptor asset=getAssets().openFd("alarm.wav")){candidate.setDataSource(asset.getFileDescriptor(),asset.getStartOffset(),asset.getLength());}}else{if(sound==null)throw new java.io.IOException("No system alarm sound");candidate.setDataSource(this,sound);}candidate.setLooping(true);candidate.prepare();candidate.start();return candidate;}catch(Exception e){candidate.release();throw e;}}
 public void onDestroy(){timer.removeCallbacksAndMessages(null);if(player!=null){try{player.stop();}catch(Exception ignored){}player.release();}if(vibrator!=null)vibrator.cancel();if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);if(wake!=null&&wake.isHeld())wake.release();for(String id:new ArrayList<>(ringing.keySet()))try{JSONObject i=itemFor(id);if(i!=null&&i.optBoolean("flag")&&!i.optBoolean("done")&&!i.optBoolean("deleted"))Reminders.notifyReminder(this,i);}catch(Exception ignored){}current=null;sendBroadcast(new Intent(getPackageName()+".ALARM_CHANGED").setPackage(getPackageName()));super.onDestroy();}
}
